from pathlib import Path
from html import escape
import json
out=Path('verification/localized-chat-20261016')
service_pages=json.loads((out/'service-card-inventory.json').read_text(encoding='utf-8'))
s='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Paper Trail, localized chat and Notes cards</title><style>body{font:16px/1.6 Arial,sans-serif;color:#202020;background:#f3f3f3;margin:0}main{max-width:1150px;margin:auto;padding:25px}nav{display:flex;gap:15px;flex-wrap:wrap}a{color:inherit;text-underline-offset:4px}label{display:block}select,button{font:inherit;padding:10px;border:1px solid #202020;background:#fff;color:#202020}select{margin-bottom:15px}.gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px;margin:25px 0}figure{margin:0;background:#fff;border:1px solid #ccc;padding:16px}figcaption{font-weight:bold;margin-bottom:15px}img{display:block;width:390px;max-width:100%;height:auto;margin:auto}li{margin-bottom:8px}@media(max-width:750px){.gallery{grid-template-columns:1fr}}</style></head><body><main><h1>Localized chat and Notes cards</h1><nav><a href="../../index.html">Open Home</a><a href="../../blog.html">Open Blog</a><a href="../../notes.html">Open Notes</a></nav><p>Home and Blog support buttons now open the guided conversation in the selected language. The same question order, canonical answer values and existing delivery fields are preserved. Questions, options, validation, review, editing and confirmation have saved local translations for all ten languages. Right to left chat text is supported.</p><p>Home Notes cards are unchanged. Their heading now sits above the All Notes button on phones. The unwanted Blog button is removed from Notes, with a moderate gap before Get Bookkeeping Support. All twelve service pages use the same photo left, title and Read button right composition as the About service cards, with photos filling their full image areas.</p><p>Verified 40 complete guided flows and 560 questions across Home and Blog at 320 and 390 pixels, plus 20 mocked delivery confirmations and 60 service page and width combinations. Native phone digit formats also passed. No real inquiry, Google API call, commit, push or publication occurred. Saved translations are locally authored; independent speaker review remains pending.</p><h2>Actual chat screenshots</h2><label for="chat-page">Page</label><select id="chat-page"><option value="blog">Blog</option><option value="index">Home</option></select><label for="chat-language">Language</label><select id="chat-language"><option value="hy">Հայերեն</option><option value="en">English</option><option value="es">Español</option><option value="fa">فارسی</option><option value="zh-CN">简体中文</option><option value="ko">한국어</option><option value="tl">Tagalog</option><option value="te">తెలుగు</option><option value="ru">Русский</option><option value="ar">العربية</option></select><div class="gallery"><figure><figcaption>First question in the selected language</figcaption><a id="chat-link" href="screenshots/blog-hy-question.png"><img id="chat-image" src="screenshots/blog-hy-question.png" alt="Actual translated guided chat screenshot"></a></figure><figure><figcaption>Translated review with right to left text</figcaption><a href="screenshots/blog-fa-review.png"><img loading="lazy" src="screenshots/blog-fa-review.png" alt="Persian chat review screenshot"></a></figure></div><h2>Notes layout</h2><div class="gallery">'''
for file,label in [('home-notes-heading-hy-390.png','Home Notes heading above its button, cards preserved'),('home-notes-heading-en-390.png','English Home Notes heading'),('notes-layout-390.png','Notes without the unwanted Blog button'),('balancing-corrections-390.png','Balancing and Corrections Notes cards'),('tax-ready-bookkeeping-390.png','Tax Ready Bookkeeping Notes cards'),('bank-credit-card-balancing-390.png','Bank and Credit Card Balancing Notes cards')]:
 s+='<figure><figcaption>'+escape(label)+'</figcaption><a href="screenshots/'+file+'"><img loading="lazy" src="screenshots/'+file+'" alt="'+escape(label)+'"></a></figure>'
s+='''</div><h2>All service pages</h2><p>Each page has four Notes cards. Open the page at phone width to inspect the universal layout.</p><ul>'''
for row in service_pages:s+='<li><a href="../../'+row['page']+'">'+escape(row['page'].replace('.html','').replace('-',' ').title())+'</a></li>'
s+='''</ul><nav><a href="screenshots/balancing-corrections-320.png">Small phone cards</a><a href="screenshots/balancing-corrections-834.png">iPad cards</a><a href="screenshots/balancing-corrections-1440.png">Desktop cards</a></nav><script>function updateChat(){const path='screenshots/'+document.querySelector('#chat-page').value+'-'+document.querySelector('#chat-language').value+'-question.png';document.querySelector('#chat-image').src=path;document.querySelector('#chat-link').href=path}document.querySelectorAll('select').forEach(e=>e.addEventListener('change',updateChat))</script></main></body></html>'''
(out/'review.html').write_text(s,encoding='utf-8')
import re
missing=[src for src in re.findall(r'<img[^>]*src="([^"]+)"',s) if not (out/src).is_file()]
assert not missing,missing
print('Localized chat and universal service Notes screenshot review created.')
